import app from './worker-v138.js';

const JSON_HEADERS={'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'};
const json=(value,status=200,headers={})=>new Response(JSON.stringify(value),{status,headers:{...JSON_HEADERS,...headers}});
const now=()=>new Date().toISOString();
const uid=prefix=>`${prefix}${crypto.randomUUID().replaceAll('-','')}`;
const publicId=prefix=>`${prefix}-${crypto.randomUUID().replaceAll('-','').slice(0,16).toUpperCase()}`;
const clean=(value,max=5000)=>String(value??'').replace(/\0/g,'').trim().slice(0,max);
const bool=value=>value===true||value===1||value==='1';
const safeJson=(value,fallback={})=>{try{return JSON.parse(value||'')}catch{return fallback}};
const safeUrl=value=>{try{const url=new URL(clean(value,1000));return url.protocol==='https:'?url.href:null}catch{return null}};
const array=(value,max=30)=>[...new Set((Array.isArray(value)?value:String(value||'').split(',')).map(item=>clean(item,180)).filter(Boolean))].slice(0,max);
const normalized=value=>clean(value,500).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();
const words=value=>new Set(normalized(value).split(' ').filter(word=>word.length>2));
const overlap=(a,b)=>{const left=words(a),right=words(b);if(!left.size||!right.size)return 0;let count=0;for(const word of left)if(right.has(word))count+=1;return count/Math.max(left.size,right.size)};
const cookie=(request,name)=>{for(const part of(request.headers.get('cookie')||'').split(';')){const[key,...value]=part.trim().split('=');if(key===name)return decodeURIComponent(value.join('='))}return''};
async function sha(value){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(value)));return[...new Uint8Array(digest)].map(byte=>byte.toString(16).padStart(2,'0')).join('')}
async function buyerSession(request,env){const token=cookie(request,'still_buyer');if(!token)return null;return env.DB.prepare(`SELECT a.id buyer_account_id,a.name FROM buyer_sessions s JOIN buyer_accounts a ON a.id=s.buyer_account_id WHERE s.token_hash=? AND s.expires_at>? AND a.status='active'`).bind(await sha(token),now()).first()}
async function companySession(request,env){const token=cookie(request,'still_company');if(!token)return null;return env.DB.prepare(`SELECT m.id member_id,m.role,o.id organization_id,o.slug,o.name organization_name,o.status organization_status FROM merchant_sessions s JOIN merchant_members m ON m.id=s.member_id JOIN merchant_organizations o ON o.id=m.organization_id WHERE s.token_hash=? AND s.expires_at>? AND m.status='active'`).bind(await sha(token),now()).first()}
const canWrite=company=>company&&['owner','admin','manager'].includes(company.role);
const sameOrigin=request=>!request.headers.get('origin')||request.headers.get('origin')===new URL(request.url).origin;
const log=(event,fields={})=>console.log(JSON.stringify({scope:'still_company_network_completion',event,at:now(),...fields}));

const TABLES=[
  `CREATE TABLE IF NOT EXISTS company_network_thing_products(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,buyer_account_id TEXT NOT NULL,thing_passport_id TEXT NOT NULL,organization_id TEXT NOT NULL,product_id TEXT NOT NULL,variant_id TEXT,source_type TEXT NOT NULL,source_public_id TEXT,provenance_json TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'CONFIRMED',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(buyer_account_id,thing_passport_id,product_id))`,
  `CREATE TABLE IF NOT EXISTS company_network_fulfillment_events(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,order_id TEXT NOT NULL,organization_id TEXT NOT NULL,fulfillment_status TEXT NOT NULL,evidence_reference TEXT NOT NULL,details_json TEXT NOT NULL DEFAULT '{}',created_by_member_id TEXT NOT NULL,created_at TEXT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS company_network_rate_limits(rate_key TEXT PRIMARY KEY,action TEXT NOT NULL,window_started_at TEXT NOT NULL,request_count INTEGER NOT NULL,expires_at TEXT NOT NULL)`,
  `CREATE INDEX IF NOT EXISTS idx_cn_thing_products_owner ON company_network_thing_products(buyer_account_id,thing_passport_id,updated_at DESC)`,
  `CREATE INDEX IF NOT EXISTS idx_cn_thing_products_product ON company_network_thing_products(product_id,status)`,
  `CREATE INDEX IF NOT EXISTS idx_cn_fulfillment_order ON company_network_fulfillment_events(order_id,created_at DESC)`,
  `CREATE INDEX IF NOT EXISTS idx_cn_rate_expiry ON company_network_rate_limits(expires_at)`
];
const COLUMNS={
  company_network_public_profiles:[['logo_url','TEXT'],['public_address','TEXT'],['service_regions_json',"TEXT NOT NULL DEFAULT '[]'"],['support_channels_json',"TEXT NOT NULL DEFAULT '[]'"],['fulfillment_modes_json',"TEXT NOT NULL DEFAULT '[]'"],['onboarding_level','INTEGER NOT NULL DEFAULT 1']],
  company_network_products:[['manufacturer','TEXT'],['media_json',"TEXT NOT NULL DEFAULT '[]'"],['support_policy_id','TEXT'],['interoperability_json',"TEXT NOT NULL DEFAULT '{}'" ]],
  company_network_offers:[['shipping_modes_json',"TEXT NOT NULL DEFAULT '[]'"],['pickup_locations_json',"TEXT NOT NULL DEFAULT '[]'"],['estimated_delivery_min_days','INTEGER'],['estimated_delivery_max_days','INTEGER'],['tax_included','INTEGER'],['refurbished_grade','TEXT'],['refurbisher_name','TEXT'],['refurbishment_policy','TEXT'],['condition_evidence_json',"TEXT NOT NULL DEFAULT '{}'" ]],
  company_network_orders:[['subtotal_cents','INTEGER'],['fees_cents','INTEGER'],['shipping_cents','INTEGER'],['tax_cents','INTEGER'],['fulfillment_status',"TEXT NOT NULL DEFAULT 'UNFULFILLED'"],['delivery_method','TEXT'],['pickup_location','TEXT'],['shipping_address_json','TEXT'],['fulfillment_provider','TEXT'],['tracking_reference','TEXT'],['tracking_url','TEXT'],['shipped_at','TEXT'],['delivered_at','TEXT'],['refunded_at','TEXT']],
  company_network_order_items:[['total_price_cents','INTEGER'],['passport_creation_policy',"TEXT NOT NULL DEFAULT 'ON_CONFIRMED_PURCHASE'"],['purchase_snapshot_json',"TEXT NOT NULL DEFAULT '{}'" ]],
  company_network_relationships:[['status',"TEXT NOT NULL DEFAULT 'ACTIVE'"],['repair_access','INTEGER NOT NULL DEFAULT 0'],['safety_notice_access','INTEGER NOT NULL DEFAULT 1'],['accessory_compatibility_access','INTEGER NOT NULL DEFAULT 0']],
  company_network_support_requests:[['shared_fields_json',"TEXT NOT NULL DEFAULT '[]'"],['evidence_json',"TEXT NOT NULL DEFAULT '[]'"],['resolution_json',"TEXT NOT NULL DEFAULT '{}'"],['refund_status','TEXT']]
};
let schemaReady;
async function ensureSchema(env){if(!schemaReady)schemaReady=(async()=>{await env.DB.batch(TABLES.map(statement=>env.DB.prepare(statement)));for(const[table,columns]of Object.entries(COLUMNS)){const info=await env.DB.prepare(`PRAGMA table_info(${table})`).all(),existing=new Set((info.results||[]).map(column=>column.name));for(const[column,definition]of columns)if(!existing.has(column))await env.DB.prepare(`ALTER TABLE ${table} ADD COLUMN ${column} ${definition}`).run()}await env.DB.prepare(`DELETE FROM company_network_rate_limits WHERE expires_at<?`).bind(now()).run()})().catch(error=>{schemaReady=undefined;throw error});await schemaReady}

async function bootstrap(request,env,ctx){const url=new URL(request.url);url.pathname='/api/v1/company-network/catalog';url.search='limit=1';await app.fetch(new Request(url,{headers:request.headers}),env,ctx);await ensureSchema(env)}
async function rateLimit(request,env,action,limit,windowSeconds=600){const buyer=await buyerSession(request,env),token=cookie(request,'still_company'),identity=buyer?.buyer_account_id||token||request.headers.get('cf-connecting-ip')||'anonymous',window=Math.floor(Date.now()/(windowSeconds*1000)),key=await sha(`${action}:${identity}:${window}`),started=new Date(window*windowSeconds*1000).toISOString(),expires=new Date((window+1)*windowSeconds*1000).toISOString();await env.DB.prepare(`INSERT INTO company_network_rate_limits(rate_key,action,window_started_at,request_count,expires_at) VALUES(?,?,?,?,?) ON CONFLICT(rate_key) DO UPDATE SET request_count=request_count+1`).bind(key,action,started,1,expires).run();const row=await env.DB.prepare(`SELECT request_count FROM company_network_rate_limits WHERE rate_key=?`).bind(key).first();return Number(row?.request_count||0)>limit?json({error:'rate_limited',retryAfterSeconds:windowSeconds},429,{'retry-after':String(windowSeconds)}):null}
async function responseData(response){return response.clone().json().catch(()=>null)}
function replaceJson(response,data){return json(data,response.status)}

const FULFILLMENT_MODES=new Set(['SHIPPING','PICKUP','DIGITAL','COMPANY_ARRANGED']);
const REFURBISHED_GRADES=new Set(['A','B','C','EXCELLENT','VERY_GOOD','GOOD','FAIR']);
function validateOffer(body){const modes=array(body?.shippingModes,8).map(value=>value.toUpperCase());if(!modes.length||modes.some(mode=>!FULFILLMENT_MODES.has(mode)))return'fulfillment_mode_required';if(modes.includes('PICKUP')&&!array(body.pickupLocations,20).length)return'pickup_location_required';const min=body.estimatedDeliveryMinDays==null||body.estimatedDeliveryMinDays===''?null:Number(body.estimatedDeliveryMinDays),max=body.estimatedDeliveryMaxDays==null||body.estimatedDeliveryMaxDays===''?null:Number(body.estimatedDeliveryMaxDays);if((min!==null&&(!Number.isInteger(min)||min<0||min>365))||(max!==null&&(!Number.isInteger(max)||max<0||max>365))||(min!==null&&max!==null&&max<min))return'invalid_delivery_estimate';if(clean(body?.condition,30).toUpperCase()==='REFURBISHED'){if(!REFURBISHED_GRADES.has(clean(body.refurbishedGrade,30).toUpperCase()))return'refurbished_grade_required';if(clean(body.refurbisherName,180).length<2)return'refurbisher_identity_required';if(clean(body.refurbishmentPolicy,2000).length<10)return'refurbishment_policy_required';if(clean(body.conditionEvidence,2000).length<10)return'refurbishment_evidence_required';if(!clean(body.warrantyPolicyId,80))return'refurbished_warranty_required'}return null}

async function enrichProfile(env,company,id,body){await env.DB.prepare(`UPDATE company_network_public_profiles SET logo_url=?,public_address=?,service_regions_json=?,support_channels_json=?,fulfillment_modes_json=?,onboarding_level=?,updated_at=? WHERE organization_id=?`).bind(body.logoUrl?safeUrl(body.logoUrl):null,clean(body.publicAddress,500)||null,JSON.stringify(array(body.serviceRegions,40)),JSON.stringify(array(body.supportChannels,20)),JSON.stringify(array(body.fulfillmentModes,8).map(value=>value.toUpperCase()).filter(value=>FULFILLMENT_MODES.has(value))),Math.min(5,Math.max(1,Number(body.onboardingLevel)||1)),now(),company.organization_id).run()}
async function enrichProduct(env,company,productId,body){const support=body.supportPolicyId?await env.DB.prepare(`SELECT id FROM company_network_policies WHERE organization_id=? AND public_id=? AND policy_type='SUPPORT' AND active=1`).bind(company.organization_id,clean(body.supportPolicyId,60)).first():null;if(body.supportPolicyId&&!support)return;await env.DB.prepare(`UPDATE company_network_products SET manufacturer=?,media_json=?,support_policy_id=?,interoperability_json=?,updated_at=? WHERE organization_id=? AND public_id=?`).bind(clean(body.manufacturer,160)||clean(body.brand,120)||null,JSON.stringify(array(body.media,20).map(safeUrl).filter(Boolean)),support?.id||null,JSON.stringify({schema:'still-product-identity-v1',identifiers:{gtin:clean(body.gtin,30)||null,mpn:clean(body.manufacturerPartNumber,120)||null},complianceClaim:null}),now(),company.organization_id,productId).run()}
async function enrichOffer(env,company,offerId,body){const modes=array(body.shippingModes,8).map(value=>value.toUpperCase()),pickups=array(body.pickupLocations,20);await env.DB.prepare(`UPDATE company_network_offers SET shipping_modes_json=?,pickup_locations_json=?,estimated_delivery_min_days=?,estimated_delivery_max_days=?,tax_included=?,refurbished_grade=?,refurbisher_name=?,refurbishment_policy=?,condition_evidence_json=?,updated_at=? WHERE organization_id=? AND public_id=?`).bind(JSON.stringify(modes),JSON.stringify(pickups),body.estimatedDeliveryMinDays===''||body.estimatedDeliveryMinDays==null?null:Number(body.estimatedDeliveryMinDays),body.estimatedDeliveryMaxDays===''||body.estimatedDeliveryMaxDays==null?null:Number(body.estimatedDeliveryMaxDays),body.taxIncluded==null?null:(bool(body.taxIncluded)?1:0),clean(body.refurbishedGrade,30).toUpperCase()||null,clean(body.refurbisherName,180)||null,clean(body.refurbishmentPolicy,2000)||null,JSON.stringify({summary:clean(body.conditionEvidence,2000)||null,source:'COMPANY_DECLARED',recordedAt:now()}),now(),company.organization_id,offerId).run()}
function orderAddress(body){const source=body?.shippingAddress;if(!source||typeof source!=='object')return null;const address={name:clean(source.name,160)||null,line1:clean(source.line1,240),line2:clean(source.line2,240)||null,city:clean(source.city,160),postalCode:clean(source.postalCode,40),countryCode:clean(source.countryCode,2).toUpperCase(),phone:clean(source.phone,40)||null};return address.line1&&address.city&&address.postalCode&&/^[A-Z]{2}$/.test(address.countryCode)?address:null}
async function enrichOrder(env,buyer,orderId,body){const method=clean(body.deliveryMethod,30).toUpperCase(),address=orderAddress(body),pickup=clean(body.pickupLocation,500)||null;await env.DB.prepare(`UPDATE company_network_orders SET subtotal_cents=total_cents,fees_cents=0,fulfillment_status='UNFULFILLED',delivery_method=?,pickup_location=?,shipping_address_json=?,updated_at=? WHERE buyer_account_id=? AND public_id=?`).bind(method||null,pickup,address?JSON.stringify(address):null,now(),buyer.buyer_account_id,orderId).run();await env.DB.prepare(`UPDATE company_network_order_items SET total_price_cents=unit_price_cents*quantity,purchase_snapshot_json=(SELECT json_object('productName',p.name,'brand',p.brand,'model',p.model,'condition',f.condition,'priceCents',company_network_order_items.unit_price_cents,'currency',company_network_order_items.currency) FROM company_network_products p JOIN company_network_offers f ON f.id=company_network_order_items.offer_id WHERE p.id=company_network_order_items.product_id) WHERE order_id=(SELECT id FROM company_network_orders WHERE public_id=?)`).bind(orderId).run()}

async function augmentProducts(response,env,company){const data=await responseData(response);if(!data?.products?.length)return response;const rows=await env.DB.prepare(`SELECT public_id,manufacturer,media_json,support_policy_id,interoperability_json FROM company_network_products WHERE organization_id=?`).bind(company.organization_id).all(),map=new Map((rows.results||[]).map(row=>[row.public_id,row]));for(const product of data.products){const row=map.get(product.publicId);if(row)Object.assign(product,{manufacturer:row.manufacturer,media:safeJson(row.media_json,[]),supportPolicyId:row.support_policy_id,interoperability:safeJson(row.interoperability_json,{})})}return replaceJson(response,data)}
function offerExtra(row){return{shippingModes:safeJson(row.shipping_modes_json,[]),pickupLocations:safeJson(row.pickup_locations_json,[]),estimatedDelivery:{minDays:row.estimated_delivery_min_days,maxDays:row.estimated_delivery_max_days},taxIncluded:row.tax_included==null?null:!!row.tax_included,refurbishment:row.condition==='REFURBISHED'?{grade:row.refurbished_grade,refurbisher:row.refurbisher_name,policy:row.refurbishment_policy,evidence:safeJson(row.condition_evidence_json,{})}:null}}
async function augmentOffers(response,env,company){const data=await responseData(response);if(!data?.offers?.length)return response;const rows=await env.DB.prepare(`SELECT * FROM company_network_offers WHERE organization_id=?`).bind(company.organization_id).all(),map=new Map((rows.results||[]).map(row=>[row.public_id,row]));for(const offer of data.offers){const row=map.get(offer.public_id||offer.publicId);if(row)Object.assign(offer,offerExtra(row))}return replaceJson(response,data)}
async function augmentCatalog(response,env){const data=await responseData(response);if(!data?.offers?.length)return response;const ids=data.offers.map(offer=>offer.publicId),rows=[];for(const id of ids){const row=await env.DB.prepare(`SELECT * FROM company_network_offers WHERE public_id=?`).bind(id).first();if(row)rows.push(row)}const map=new Map(rows.map(row=>[row.public_id,row]));for(const offer of data.offers){const row=map.get(offer.publicId);if(row)Object.assign(offer,{fulfillment:offerExtra(row)})}return replaceJson(response,data)}
async function augmentOrders(response,env,ownerId,column){const data=await responseData(response);if(!data?.orders?.length)return response;const rows=await env.DB.prepare(`SELECT public_id,subtotal_cents,fees_cents,shipping_cents,tax_cents,fulfillment_status,delivery_method,pickup_location,shipping_address_json,fulfillment_provider,tracking_reference,tracking_url,shipped_at,delivered_at,refunded_at FROM company_network_orders WHERE ${column}=? ORDER BY created_at DESC LIMIT 200`).bind(ownerId).all(),map=new Map((rows.results||[]).map(row=>[row.public_id,row]));for(const order of data.orders){const row=map.get(order.public_id);if(row)Object.assign(order,row,{shippingAddress:safeJson(row.shipping_address_json,null)})}return replaceJson(response,data)}
async function augmentSupport(response,env,ownerId,column){const data=await responseData(response);if(!data?.requests?.length)return response;const rows=await env.DB.prepare(`SELECT public_id,shared_fields_json,evidence_json,resolution_json,refund_status FROM company_network_support_requests WHERE ${column}=? ORDER BY updated_at DESC LIMIT 200`).bind(ownerId).all(),map=new Map((rows.results||[]).map(row=>[row.public_id,row]));for(const request of data.requests){const row=map.get(request.public_id);if(row)Object.assign(request,{sharedFields:safeJson(row.shared_fields_json,[]),evidence:safeJson(row.evidence_json,[]),resolution:safeJson(row.resolution_json,{}),refundStatus:row.refund_status})}return replaceJson(response,data)}

async function catalogPage(env,url){const query=normalized(url.searchParams.get('q')||''),term=`%${query}%`,limit=Math.min(40,Math.max(1,Number(url.searchParams.get('limit'))||20));let offset=0;try{offset=Math.max(0,Math.min(100000,Number(atob(url.searchParams.get('cursor')||''))||0))}catch{}const result=await env.DB.prepare(`SELECT f.*,p.public_id product_public_id,p.name product_name,p.brand,p.model,p.category,p.description,p.gtin,v.public_id variant_public_id,v.name variant_name,o.slug company_slug,o.name company_name,o.status organization_status,COALESCE(b.on_hand-b.reserved,0) available,wp.name warranty_name,wp.summary warranty_summary,wp.duration_days warranty_days,rp.name return_name,rp.summary return_summary,rp.duration_days return_days FROM company_network_offers f JOIN company_network_products p ON p.id=f.product_id JOIN merchant_organizations o ON o.id=f.organization_id JOIN company_network_public_profiles pp ON pp.organization_id=o.id LEFT JOIN company_network_variants v ON v.id=f.variant_id LEFT JOIN inventory_balances b ON b.organization_id=f.organization_id AND b.item_id=f.inventory_item_id AND b.location_id=f.inventory_location_id LEFT JOIN company_network_policies wp ON wp.id=f.warranty_policy_id LEFT JOIN company_network_policies rp ON rp.id=f.return_policy_id WHERE f.active=1 AND p.status='ACTIVE' AND o.status='verified' AND pp.published=1 AND COALESCE(b.on_hand-b.reserved,0)>0 AND (?='%%' OR LOWER(p.name||' '||COALESCE(p.brand,'')||' '||COALESCE(p.model,'')||' '||COALESCE(p.category,'')) LIKE ?) ORDER BY f.price_cents ASC,p.name ASC,f.public_id ASC LIMIT ? OFFSET ?`).bind(term,term,limit+1,offset).all(),rows=result.results||[],hasMore=rows.length>limit,offers=rows.slice(0,limit).map(row=>({publicId:row.public_id,product:{publicId:row.product_public_id,name:row.product_name,brand:row.brand||null,model:row.model||null,category:row.category||null,description:row.description||null,gtin:row.gtin||null},variant:row.variant_public_id?{publicId:row.variant_public_id,name:row.variant_name}:null,company:{id:row.organization_id,slug:row.company_slug,name:row.company_name,verified:true},condition:row.condition,priceCents:row.price_cents,currency:row.currency,available:Math.max(0,Number(row.available||0)),checkout:{mode:row.checkout_mode,externalUrl:row.checkout_mode==='EXTERNAL'?row.external_checkout_url:null},warranty:row.warranty_name?{name:row.warranty_name,summary:row.warranty_summary,durationDays:row.warranty_days}:null,returns:row.return_name?{name:row.return_name,summary:row.return_summary,durationDays:row.return_days}:null,fulfillment:offerExtra(row)}));return json({offers,pagination:{limit,nextCursor:hasMore?btoa(String(offset+limit)):null,hasMore},ordering:'PRICE_NAME_ID',query:query||null})}

async function publicCompany(env,slug,productsOnly=false){const company=await env.DB.prepare(`SELECT o.id,o.slug,o.name,p.* FROM merchant_organizations o JOIN company_network_public_profiles p ON p.organization_id=o.id WHERE o.slug=? AND o.status='verified' AND p.published=1`).bind(slug).first();if(!company)return json({error:'company_not_found'},404);const rows=await env.DB.prepare(`SELECT p.public_id,p.name,p.brand,p.manufacturer,p.model,p.category,p.description,p.gtin,p.manufacturer_part_number,p.media_json,p.interoperability_json FROM company_network_products p WHERE p.organization_id=? AND p.status='ACTIVE' ORDER BY p.updated_at DESC LIMIT 100`).bind(company.id).all(),products=(rows.results||[]).map(row=>({...row,media:safeJson(row.media_json,[]),interoperability:safeJson(row.interoperability_json,{})}));if(productsOnly)return json({company:{slug:company.slug,name:company.display_name},products});return json({company:{slug:company.slug,name:company.display_name,description:company.description,logoUrl:company.logo_url,address:company.public_address,countryCode:company.country_code,websiteUrl:company.website_url,supportEmail:company.support_email,serviceRegions:safeJson(company.service_regions_json,[]),supportChannels:safeJson(company.support_channels_json,[]),fulfillmentModes:safeJson(company.fulfillment_modes_json,[]),verified:true},products})}
async function productExport(env,company,id){const product=await env.DB.prepare(`SELECT p.*,o.slug,o.name company_name FROM company_network_products p JOIN merchant_organizations o ON o.id=p.organization_id WHERE p.organization_id=? AND p.public_id=?`).bind(company.organization_id,id).first();if(!product)return json({error:'product_not_found'},404);const variants=await env.DB.prepare(`SELECT public_id,name,sku,gtin,attributes_json,status FROM company_network_variants WHERE product_id=? ORDER BY created_at`).bind(product.id).all();return json({format:'still-dpp-interoperability-v1',regulatoryComplianceClaim:null,notice:'Structured interoperability export; no regulatory compliance is claimed.',exportedAt:now(),company:{slug:product.slug,name:product.company_name},product:{publicId:product.public_id,name:product.name,brand:product.brand,manufacturer:product.manufacturer,model:product.model,category:product.category,description:product.description,identifiers:{gtin:product.gtin,mpn:product.manufacturer_part_number},specifications:safeJson(product.specifications_json,{}),media:safeJson(product.media_json,[]),provenance:safeJson(product.provenance_json,{})},variants:(variants.results||[]).map(row=>({...row,attributes:safeJson(row.attributes_json,{})}))})}

async function receiptMatches(env,buyer,receiptId){const receipt=await env.DB.prepare(`SELECT id,public_id,merchant,purchase_date,currency FROM world_receipts WHERE buyer_account_id=? AND public_id=? AND archived_at IS NULL`).bind(buyer.buyer_account_id,receiptId).first();if(!receipt)return null;const items=await env.DB.prepare(`SELECT id,public_id,title,raw_label,total_cents,gtin,manufacturer_candidate,model_candidate,thing_passport_id FROM world_receipt_items WHERE buyer_account_id=? AND receipt_id=? ORDER BY created_at`).bind(buyer.buyer_account_id,receipt.id).all(),products=await env.DB.prepare(`SELECT p.id,p.public_id,p.name,p.brand,p.manufacturer,p.model,p.gtin,o.id organization_id,o.name company_name,pp.display_name FROM company_network_products p JOIN merchant_organizations o ON o.id=p.organization_id JOIN company_network_public_profiles pp ON pp.organization_id=o.id WHERE p.status='ACTIVE' AND o.status='verified' AND pp.published=1 LIMIT 500`).all(),matches={};for(const item of items.results||[]){const candidates=[];for(const product of products.results||[]){let confidence=0;const reasons=[];if(item.gtin&&product.gtin&&item.gtin===product.gtin){confidence=100;reasons.push('GTIN_EXACT')}const modelExact=item.model_candidate&&product.model&&normalized(item.model_candidate)===normalized(product.model),makerExact=item.manufacturer_candidate&&[product.brand,product.manufacturer].some(value=>value&&normalized(value)===normalized(item.manufacturer_candidate));if(modelExact&&makerExact&&confidence<96){confidence=96;reasons.push('MANUFACTURER_AND_MODEL_EXACT')}else if(modelExact&&confidence<90){confidence=90;reasons.push('MODEL_EXACT')}const titleScore=Math.max(overlap(item.title,`${product.brand||''} ${product.name} ${product.model||''}`),overlap(item.raw_label,`${product.brand||''} ${product.name} ${product.model||''}`)),merchantMatch=normalized(receipt.merchant)&&[product.company_name,product.display_name].some(value=>normalized(value).includes(normalized(receipt.merchant))||normalized(receipt.merchant).includes(normalized(value)));if(titleScore>=.75&&confidence<88){confidence=88;reasons.push('STRONG_LINE_ITEM_MATCH')}if(titleScore>=.6&&merchantMatch&&confidence<86){confidence=86;reasons.push('MERCHANT_AND_LINE_ITEM_MATCH')}if(confidence>=85)candidates.push({productId:product.public_id,companyName:product.display_name||product.company_name,name:product.name,brand:product.brand,model:product.model,confidence,reasons,requiresConfirmation:true})}matches[item.public_id]=candidates.sort((a,b)=>b.confidence-a.confidence||a.productId.localeCompare(b.productId)).slice(0,3)}return{receiptId:receipt.public_id,matchingRule:'DETERMINISTIC_HIGH_CONFIDENCE_ONLY',notice:'A match is never linked without confirmation.',items:(items.results||[]).map(item=>({receiptItemId:item.public_id,thingLinked:!!item.thing_passport_id,matches:matches[item.public_id]||[]}))}}
async function linkReceiptMatch(request,env,buyer,receiptId,body){const item=await env.DB.prepare(`SELECT i.*,p.public_id thing_public_id FROM world_receipt_items i JOIN world_receipts r ON r.id=i.receipt_id LEFT JOIN ownership_passports p ON p.id=i.thing_passport_id WHERE r.buyer_account_id=? AND r.public_id=? AND i.public_id=?`).bind(buyer.buyer_account_id,receiptId,clean(body.receiptItemId,60)).first();if(!item?.thing_passport_id)return json({error:'confirmed_receipt_thing_required'},409);const product=await env.DB.prepare(`SELECT p.*,o.id organization_id FROM company_network_products p JOIN merchant_organizations o ON o.id=p.organization_id JOIN company_network_public_profiles pp ON pp.organization_id=o.id WHERE p.public_id=? AND p.status='ACTIVE' AND o.status='verified' AND pp.published=1`).bind(clean(body.productId,60)).first();if(!product)return json({error:'product_not_found'},404);const matches=await receiptMatches(env,buyer,receiptId),candidate=matches?.items.find(row=>row.receiptItemId===item.public_id)?.matches.find(row=>row.productId===product.public_id);if(!candidate)return json({error:'high_confidence_match_not_found'},422);const profile=await env.DB.prepare(`SELECT gtin,manufacturer,model FROM world_thing_profiles WHERE passport_id=? AND buyer_account_id=?`).bind(item.thing_passport_id,buyer.buyer_account_id).first(),conflicts=[];if(profile?.gtin&&product.gtin&&profile.gtin!==product.gtin)conflicts.push({field:'gtin',existing:profile.gtin,official:product.gtin});if(profile?.model&&product.model&&normalized(profile.model)!==normalized(product.model))conflicts.push({field:'model',existing:profile.model,official:product.model});if(conflicts.length&&!bool(body.confirmConflict))return json({error:'identity_conflict',conflicts,notice:'Existing evidence was not overwritten.'},409);const ts=now();await env.DB.prepare(`INSERT INTO company_network_thing_products(id,public_id,buyer_account_id,thing_passport_id,organization_id,product_id,source_type,source_public_id,provenance_json,status,created_at,updated_at) VALUES(?,?,?,?,?,?,'RECEIPT_MATCH',?,?, 'CONFIRMED',?,?) ON CONFLICT(buyer_account_id,thing_passport_id,product_id) DO UPDATE SET provenance_json=excluded.provenance_json,status='CONFIRMED',updated_at=excluded.updated_at`).bind(uid('ctp_'),publicId('LNK'),buyer.buyer_account_id,item.thing_passport_id,product.organization_id,product.id,receiptId,JSON.stringify({confidence:candidate.confidence,reasons:candidate.reasons,userConfirmed:true,conflictsAcknowledged:conflicts.length>0}),ts,ts).run();log('receipt_product_match_confirmed',{buyerId:buyer.buyer_account_id,receiptId,productId:product.public_id});return json({ok:true,thingId:item.thing_public_id,productId:product.public_id,companyAccessGranted:false,existingEvidencePreserved:true})}

async function linkClaimIdentity(env,buyerId,token,response){const data=await responseData(response);if(!response.ok||!data?.thingId)return response;const row=await env.DB.prepare(`SELECT t.product_id,t.variant_id,t.organization_id,p.id thing_id FROM company_network_claim_tokens t JOIN ownership_passports p ON p.public_id=? AND p.buyer_account_id=? WHERE t.token_hash=?`).bind(data.thingId,buyerId,await sha(token)).first();if(row){const ts=now();await env.DB.prepare(`INSERT INTO company_network_thing_products(id,public_id,buyer_account_id,thing_passport_id,organization_id,product_id,variant_id,source_type,source_public_id,provenance_json,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'QR_CLAIM',?,?,'CONFIRMED',?,?) ON CONFLICT(buyer_account_id,thing_passport_id,product_id) DO UPDATE SET variant_id=excluded.variant_id,source_type='QR_CLAIM',provenance_json=excluded.provenance_json,status='CONFIRMED',updated_at=excluded.updated_at`).bind(uid('ctp_'),publicId('LNK'),buyerId,row.thing_id,row.organization_id,row.product_id,row.variant_id,null,JSON.stringify({source:'COMPANY_QR',userConfirmed:true}),ts,ts).run()}return response}
async function linkOrderIdentity(env,company,orderId,response){const data=await responseData(response);if(!response.ok||!data?.thingId)return response;const row=await env.DB.prepare(`SELECT o.buyer_account_id,o.organization_id,oi.product_id,oi.variant_id,oi.thing_passport_id FROM company_network_orders o JOIN company_network_order_items oi ON oi.order_id=o.id WHERE o.organization_id=? AND o.public_id=?`).bind(company.organization_id,orderId).first();if(row?.thing_passport_id){const ts=now();await env.DB.prepare(`INSERT INTO company_network_thing_products(id,public_id,buyer_account_id,thing_passport_id,organization_id,product_id,variant_id,source_type,source_public_id,provenance_json,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'STILL_PURCHASE',?,?,'CONFIRMED',?,?) ON CONFLICT(buyer_account_id,thing_passport_id,product_id) DO UPDATE SET source_type='STILL_PURCHASE',provenance_json=excluded.provenance_json,status='CONFIRMED',updated_at=excluded.updated_at`).bind(uid('ctp_'),publicId('LNK'),row.buyer_account_id,row.thing_passport_id,row.organization_id,row.product_id,row.variant_id,orderId,JSON.stringify({source:'CONFIRMED_ORDER',orderId}),ts,ts).run()}return response}

