async function completeSupportResolution(env,company,body,response){if(!response.ok||!body?.requestId)return response;const status=clean(body.status,30).toUpperCase(),resolutionType=clean(body.resolutionType,40).toUpperCase(),refundStatus=clean(body.refundStatus,40).toUpperCase()||null,evidenceReference=clean(body.evidenceReference,240);if(status!=='RESOLVED'||!resolutionType)return response;if(evidenceReference.length<3)return json({error:'resolution_evidence_required'},422);const row=await env.DB.prepare(`SELECT s.*,p.public_id thing_public_id FROM company_network_support_requests s JOIN ownership_passports p ON p.id=s.thing_passport_id WHERE s.organization_id=? AND s.public_id=?`).bind(company.organization_id,clean(body.requestId,60)).first();if(!row)return response;const ts=now();await env.DB.prepare(`UPDATE company_network_support_requests SET resolution_json=?,refund_status=?,updated_at=? WHERE id=?`).bind(JSON.stringify({type:resolutionType,evidenceReference,resolvedAt:ts}),refundStatus,ts,row.id).run();if(row.request_type==='RETURN'&&resolutionType==='RETURN_ACCEPTED'){await env.DB.batch([env.DB.prepare(`UPDATE world_thing_profiles SET lifecycle_state='RETURNED',updated_at=? WHERE passport_id=? AND buyer_account_id=?`).bind(ts,row.thing_passport_id,row.buyer_account_id),env.DB.prepare(`UPDATE ownership_passports SET status='archived',updated_at=? WHERE id=? AND buyer_account_id=?`).bind(ts,row.thing_passport_id,row.buyer_account_id),env.DB.prepare(`INSERT INTO world_history_events(id,public_id,buyer_account_id,entity_type,entity_public_id,event_type,title,details_json,source_type,source_public_id,occurred_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)`).bind(uid('whe_'),publicId('HIS'),row.buyer_account_id,'thing',row.thing_public_id,'thing.returned','Returned to company',JSON.stringify({requestId:row.public_id,refundStatus,evidenceReference}),'company_network',row.public_id,ts,ts)]);log('return_completed',{organizationId:company.organization_id,requestId:row.public_id,refundStatus})}return response}

async function augmentThing(response,env,buyer,id){const data=await responseData(response);if(!response.ok||!data?.thing)return response;const row=await env.DB.prepare(`SELECT l.public_id link_id,l.source_type,l.provenance_json,p.public_id product_id,p.name,p.brand,p.manufacturer,p.model,p.gtin,p.manufacturer_part_number,p.specifications_json,p.media_json,o.slug company_slug,o.name company_name,r.public_id relationship_id,r.support_access,r.warranty_access,r.repair_access,r.service_history_access,r.product_update_access,r.safety_notice_access,r.revoked_at,wp.name warranty_name,wp.summary warranty_summary,wp.duration_days warranty_days,ord.confirmed_at purchase_confirmed_at FROM company_network_thing_products l JOIN company_network_products p ON p.id=l.product_id JOIN merchant_organizations o ON o.id=l.organization_id LEFT JOIN company_network_relationships r ON r.buyer_account_id=l.buyer_account_id AND r.organization_id=l.organization_id AND r.thing_passport_id=l.thing_passport_id LEFT JOIN company_network_order_items oi ON oi.thing_passport_id=l.thing_passport_id LEFT JOIN company_network_orders ord ON ord.id=oi.order_id LEFT JOIN company_network_offers f ON f.id=oi.offer_id LEFT JOIN company_network_policies wp ON wp.id=f.warranty_policy_id JOIN ownership_passports op ON op.id=l.thing_passport_id WHERE l.buyer_account_id=? AND op.public_id=? AND l.status='CONFIRMED' ORDER BY l.updated_at DESC LIMIT 1`).bind(buyer.buyer_account_id,id).first();if(!row)return response;let warranty=null;if(row.warranty_name){const starts=row.purchase_confirmed_at||data.thing.purchaseDate||null,expires=starts&&row.warranty_days?new Date(new Date(starts).getTime()+Number(row.warranty_days)*86400000).toISOString():null;warranty={name:row.warranty_name,summary:row.warranty_summary,durationDays:row.warranty_days,startsAt:starts,expiresAt:expires,status:expires?(expires>now()?'ACTIVE':'EXPIRED'):'TERMS_AVAILABLE'}}data.thing.officialProduct={publicId:row.product_id,name:row.name,brand:row.brand,manufacturer:row.manufacturer,model:row.model,identifiers:{gtin:row.gtin,mpn:row.manufacturer_part_number},specifications:safeJson(row.specifications_json,{}),media:safeJson(row.media_json,[]),company:{slug:row.company_slug,name:row.company_name},source:row.source_type,provenance:safeJson(row.provenance_json,{})};data.thing.companyRelationship=row.relationship_id?{publicId:row.relationship_id,active:!row.revoked_at,permissions:{support:!!row.support_access,warranty:!!row.warranty_access,repair:!!row.repair_access,serviceHistory:!!row.service_history_access,productUpdates:!!row.product_update_access,safetyNotices:!!row.safety_notice_access}}:null;data.thing.warranty=warranty;return replaceJson(response,data)}

