  const custom=path==='/api/v1/company-network/catalog'||/^\/api\/v1\/(?:companies\/|company-network\/(?:claims\/batch|customers|products\/[^/]+\/export|orders\/[^/]+\/fulfillment)|world\/receipts\/[^/]+\/company-match)/.test(path);
